// TymuxServiceHandler is an implementation of the tymux.v1.TymuxService service.
type TymuxServiceHandler interface {
	// Reports the daemon's build version, wire-protocol revision, and optional
	// capabilities, so a client can decide whether it can talk to this daemon
	// (and which newer features it may use) before issuing anything else. See
	// docs/adr/0003-protocol-versioning.md for the compatibility policy. A
	// daemon older than this RPC (<= 1.3.0) answers UNIMPLEMENTED, which
	// clients should treat as "pre-versioning, protocol 0".
	GetServerInfo(context.Context, *connect.Request[v1.GetServerInfoRequest]) (*connect.Response[v1.ServerInfo], error)
	CreateSession(context.Context, *connect.Request[v1.CreateSessionRequest]) (*connect.Response[v1.Session], error)
	ListSessions(context.Context, *connect.Request[v1.ListSessionsRequest]) (*connect.Response[v1.ListSessionsResponse], error)
	KillSession(context.Context, *connect.Request[v1.KillSessionRequest]) (*connect.Response[v1.KillSessionResponse], error)
	// Respawns fresh ptys for a dead-flagged (restored-but-not-yet-revived)
	// session, matching its persisted Layout shape — each pane's original
	// command re-run in its persisted cwd. Never triggered automatically on
	// daemon start (ADR-002); only an explicit call reaches this. A no-op
	// (ReviveSessionResponse.already_live=true) if the session is already
	// live — never a duplicate spawn. A pane whose child exited inside this daemon (not
	// restored from disk) is also respawned in place, same pane id and screen (ADR-0007);
	// before that, such a session was reported already_live and nothing was respawned.
	// A pane the operator stopped (STOPPED, StopPane) or that ran out of restarts (FAILED)
	// is never revived by this call: it stays as it is while the session's other panes are
	// revived, and pane_count counts only the panes started. If every pane is STOPPED or
	// FAILED the call is FAILED_PRECONDITION. Use
	// StartPane (STOPPED or FAILED) or RestartPane (resets the budget) for those.
	ReviveSession(context.Context, *connect.Request[v1.ReviveSessionRequest]) (*connect.Response[v1.ReviveSessionResponse], error)
	// One-shot structured read of a pane's current screen — the AI-friendly
	// alternative to `tmux capture-pane` (which returns raw text you'd have
	// to re-parse). Cells carry attributes directly. scrollback_offset lets
	// a caller read a historical screen (copy-mode's navigation primitive)
	// instead of the live one.
	CapturePane(context.Context, *connect.Request[v1.CapturePaneRequest]) (*connect.Response[v1.PaneSnapshot], error)
	// Forward-only substring search through a pane's scrollback — the
	// direct, non-interactive access path for programmatic/agent callers
	// (one shared history buffer, two access paths: this and CapturePane's
	// scrollback_offset).
	SearchScrollback(context.Context, *connect.Request[v1.SearchScrollbackRequest]) (*connect.Response[v1.SearchScrollbackResponse], error)
	// Splits an existing pane into two, nesting a new Split node in its
	// window's Layout tree in the target pane's place. Rejected with
	// failed_precondition (naming the actual/minimum rows+cols) if the
	// resulting leaf would fall below the daemon's hard minimum pane size.
	SplitPane(context.Context, *connect.Request[v1.SplitPaneRequest]) (*connect.Response[v1.Session], error)
	// Closes one pane. If it was the last pane in its window, the window
	// itself closes (cascading to KillSession if it was also the session's
	// last window) — see ClosePaneResponse.window_closed/session_closed.
	ClosePane(context.Context, *connect.Request[v1.ClosePaneRequest]) (*connect.Response[v1.ClosePaneResponse], error)
	// Adds a new window (single pane) to an existing session.
	CreateWindow(context.Context, *connect.Request[v1.CreateWindowRequest]) (*connect.Response[v1.Session], error)
	// Streams the subscribed window's Layout every time its structure or
	// geometry changes, so a client's local model stays in sync without
	// polling ListSessions.
	WatchWindow(context.Context, *connect.Request[v1.WatchWindowRequest], *connect.ServerStream[v1.WindowLayoutEvent]) error
	// Bidirectional stream: client sends input/resize events, server streams
	// output back. This is what an interactive attach (human or agent) uses.
	//
	// Contract:
	//   - The first AttachRequest on the stream MUST set the pane_id field of
	//     the oneof; any other first message is rejected with
	//     invalid_argument.
	//   - Detaching means fully cancelling this call (dropping/closing both
	//     directions). Half-closing only the send side does not stop the
	//     receive side or end the attach — the server keeps streaming output
	//     until the whole call is cancelled.
	//   - output_gap=true on an AttachEvent means the server's internal
	//     output broadcast channel dropped frames for this consumer (it fell
	//     behind); some output between the previous and next Output event was
	//     lost. This is not a fatal condition — normal streaming resumes
	//     immediately after.
	//   - Resize is now window-scoped, not pane-scoped (ADR-004): the
	//     daemon tracks every attached client's reported viewport per window
	//     and applies the dimension-wise minimum across all of them, rather
	//     than sizing this one pane to this one client's last report.
	//
	// Epic 1.1: shared reconnect-loop specification. This is the one
	// contract `tymux-cli`, `clients/ts`, and `clients/go` (Epics 5.1, 5.2,
	// 6.1) must all implement identically — do not reinvent per client.
	//   - resume_from_seq (AttachRequest, outside the oneof) is bound to the
	//     pane_id carried by that same first message on the stream; it has
	//     no meaning attached to any other message. Omitting it (None) is a
	//     full attach and behaves identically to a pre-feature client: the
	//     daemon responds with a PaneSnapshot priming event, as it always
	//     has. Setting it to Some(n) asks the daemon to replay OutputChunk
	//     events from its per-pane ReplayBuffer starting at seq n+1, skipping
	//     the PaneSnapshot, PROVIDED seq n+1 is still retained.
	//   - GapExceeded means the requested resume_from_seq is older than
	//     anything the ReplayBuffer still retains — the gap cannot be closed
	//     by replay. A GapExceeded event is always immediately followed by a
	//     PaneSnapshot event, which the client MUST treat as authoritative:
	//     discard any locally buffered partial/replayed state and redraw
	//     from the snapshot, exactly as a fresh (non-resuming) attach would.
	//   - Heartbeat is an empty keepalive sent on an application-level
	//     interval during an otherwise-idle stream, so a client can tell
	//     "connected but quiet" apart from a silently-dead transport without
	//     relying solely on TCP/HTTP2-level timeouts. It carries no data and
	//     requires no client response.
	//   - Reconnect backoff policy (ADR-004, revised): on stream failure, a
	//     conforming client retries with exponential backoff starting at
	//     200ms, doubling each attempt (x2 multiplier), capped at 8s per
	//     attempt, with +/-20% jitter, giving up after 14 attempts (nominal
	//     cumulative backoff ~68.6s). This ceiling is deliberately chosen to
	//     be >= the daemon's grace_period_duration (60s), so a client that
	//     keeps retrying on this schedule has a real chance of reconnecting
	//     before the daemon gives up on the pane's grace period.
	Attach(context.Context, *connect.BidiStream[v1.AttachRequest, v1.AttachEvent]) error
	// Streams bytes into the stdin of a pane created with
	// CreateSessionRequest.stdin_stream (ADR-0006). First message names the
	// pane; later messages carry data or a close. Bytes are written in order and
	// the call returns once every message has been written (or the stream
	// closed); writes block while the process is not reading, so a slow reader
	// applies backpressure to the client. The pipe stays open after the stream
	// ends unless a `close` was sent, so one input can span several calls.
	// FAILED_PRECONDITION: the pane is dead, was not created with stdin_stream,
	// stdin is already closed, or the process closed its stdin / exited
	// (broken pipe). Advertised as capability "create_session.stdin_stream".
	WriteStdin(context.Context, *connect.ClientStream[v1.WriteStdinRequest]) (*connect.Response[v1.WriteStdinResponse], error)
	// Sets the restart policy of one pane, or (session_id) the default for panes created later
	// in that session. Takes effect at the pane's next exit; a pending backoff the new policy
	// would not have scheduled is cancelled. INVALID_ARGUMENT for a nonsensical policy.
	SetRestartPolicy(context.Context, *connect.Request[v1.SetRestartPolicyRequest]) (*connect.Response[v1.SetRestartPolicyResponse], error)
	// The pane's lifecycle state, policy, counters and timestamps.
	GetPaneStatus(context.Context, *connect.Request[v1.GetPaneStatusRequest]) (*connect.Response[v1.PaneStatus], error)
	// Replaces the pane's process now: a running one gets SIGTERM (SIGKILL after grace) and is
	// respawned once it exits; a dead one (any state, including STOPPED and FAILED) is respawned
	// immediately. Not charged to the restart budget and not delayed. With reset_backoff the
	// backoff delay and window budget start over. Returns once the new process is running (or
	// failed to start); a failed start counts against the budget like any failed run.
	RestartPane(context.Context, *connect.Request[v1.RestartPaneRequest]) (*connect.Response[v1.PaneStatus], error)
	// SIGTERM, then SIGKILL after the grace period, and parks the pane in STOPPED: it will not
	// restart until StartPane, whatever its policy. Returns once the process is gone (or the
	// grace period plus a short margin has passed). Cancels a pending backoff.
	StopPane(context.Context, *connect.Request[v1.StopPaneRequest]) (*connect.Response[v1.PaneStatus], error)
	// Starts a pane that is STOPPED, EXITED, FAILED or in BACKOFF, with a fresh restart budget.
	// FAILED_PRECONDITION if its process is running. Also respawns a single pane restored from
	// disk after a daemon restart.
	StartPane(context.Context, *connect.Request[v1.StartPaneRequest]) (*connect.Response[v1.PaneStatus], error)
	// Clears the backoff delay and the restart budget. A FAILED pane becomes EXITED; nothing is
	// started (use StartPane).
	ResetRestartBudget(context.Context, *connect.Request[v1.ResetRestartBudgetRequest]) (*connect.Response[v1.PaneStatus], error)
}

// NewTymuxServiceHandler builds an HTTP handler from the service implementation. It returns the
